package it.unisa.ocelot.simulator;

import java.util.ArrayList;
import java.util.List;

/**
 * Collects all the {@link ExecutionEvent}s 
 * generated by running a C program over 
 * some input arguments.
 */
public class EventsHandler {
	private final ArrayList<ExecutionEvent> events;
	
	/**
	 * Constructor.
	 */
	public EventsHandler() {
		this.events = new ArrayList<>();
	}
	
	/**
	 * Registers as a new event the fact that the 
	 * execution of a C program traversed an 
	 * if statement.
	 * 
	 * @param pChoice an {@code int} code identifying   
	 *        the traversed if statement branch.
	 * @param pDistanceThen the branch distance from
	 *        the "then" branch of the if statement.        
	 * @param pDistanceElse the branch distance from
	 *        the "else" branch of the if statement.
	 */
	public void add(int pChoice, double pDistanceThen, double pDistanceElse) {
		this.events.add(new IfExecutionEvent(pChoice, pDistanceThen, pDistanceElse));
	}
	
	/**
	 * Registers as a new event the fact that the 
	 * execution of a C program traversed a
	 * switch statement. Actually, when this happens,
	 * it is necessary to register one of these events
	 * for each branch of the statement, also for the
	 * ones that are not traversed, with their
	 * respective branch distances.
	 * 
	 * @param pChoice an {@code int} code identifying   
	 *        the (traversed or not) associated 
	 *        switch statement branch.
	 * @param pDistance the branch distance from
	 *        the associated switch branch.
	 *        statement that this event represents.        
	 * @param isChosen {@code true} iff the execution
	 *        passed through the branch of the switch 
	 *        statement that this event represents.
	 */
	public void addCase(int pChoice, double pDistance, boolean isChosen) {
		this.events.add(new CaseExecutionEvent(pChoice, pDistance, isChosen));
	}
	
	/**
	 * Gets all the events.
	 * 
	 * @return a {@link List}{@code <}{@link ExecutionEvent}{@code >}
	 *         containing, in chronological order of visit, all the 
	 *         collected events.
	 */
	public List<ExecutionEvent> getEvents() {
		return new ArrayList<>(this.events); //safety copy
	}
	
	@Override
	public String toString() {
		return this.events.toString();
	}
}
